\multirow{2}{*}{\textsc{No Filter}}
  & MMLU      & 0.5887 & 0.5893 & 0.5900 & 0.5911 & 0.5904 & 0.5899$\pm$0.0008 \\
  & HellaSwag & 0.6602 & 0.6597 & 0.6603 & 0.6599 & 0.6598 & 0.6600$\pm$0.0002 \\
\midrule
\multirow{2}{*}{\textsc{Binary}}
  & MMLU      & 0.5871 & 0.5881 & 0.5872 & 0.5876 & 0.5880 & 0.5876$\pm$0.0004 \\
  & HellaSwag & 0.6641 & 0.6637 & 0.6649 & 0.6639 & 0.6641 & \textbf{0.6642$\pm$0.0004} \\
\midrule
\multirow{2}{*}{\textsc{Graduated} ($\alpha$=0.9)}
  & MMLU      & 0.5889 & 0.5887 & 0.5901 & 0.5917 & 0.5907 & \textbf{0.5900$\pm$0.0011} \\
  & HellaSwag & 0.6604 & 0.6596 & 0.6599 & 0.6598 & 0.6595 & 0.6599$\pm$0.0003 \\
\midrule
\multicolumn{8}{l}{\textit{Paired $t$-test $p$-values (vs.\ \textsc{No Filter}, $n=5$):}} \\
\midrule
\textsc{Graduated} vs.\ \textsc{No Filter}
  & MMLU & \multicolumn{5}{c}{$p = 0.692$ (n.s.)} \\
  & HellaSwag & \multicolumn{5}{c}{$p = 0.245$ (n.s.)} \\
\textsc{Binary} vs.\ \textsc{No Filter}
  & MMLU & \multicolumn{5}{c}{$p = 0.005$ (sig.)} \\
  & HellaSwag & \multicolumn{5}{c}{$p < 0.00001$ (sig.)} \\
\bottomrule
\end{tabular}
\end{table*}

